# פרק 11 (שלד אוטומטי מהתוכן הקיים; להעמקה)
N=11
TITLE='אחריות שילוחית'
SUM=[' <p>מנגנון המטיל אחריות על אדם בשל עוולה שביצע אחר — להבטחת פיצוי ולתמרוץ פיקוח ("הכיס העמוק").</p> <h3>11.1 אחריות מעביד — סעיף 13</h3> <p>מעביד חב על עוולת <strong>עובדו</strong> אם בוצעה <strong>במהלך עבודתו</strong> (אגב מילוי תפקידו) — גם אם ברשלנות או בניגוד להוראה, כל עוד היא בגדר "מסגרת ההעסקה". זהו המקרה השכיח.</p> <h3>11.2 אחריות שולח וקבלן עצמאי — סעיפים 14–15</h3> <p><strong>סעיף 14</strong>: שולח חב על עוולת שלוחו בביצוע השליחות. <strong>סעיף 15</strong>: ככלל <strong>אין</strong> אחריות שילוחית למעשי <strong>קבלן עצמאי</strong> (הפועל באופן עצמאי), למעט חריגים — רשלנות בבחירת הקבלן או חובה שאינה ניתנת להעברה.</p> <h3>11.3 הבחנת עובד מקבלן</h3> <p>מבחן ה<strong>השתלבות והפיקוח</strong>: עובד משולב בארגון ונתון לפיקוח; קבלן עצמאי פועל לחשבונו ובשליטתו. ההבחנה קובעת אם תחול אחריות שילוחית.</p> <h3>11.4 נקודות מפתח למבחן</h3> <ul><li>מעביד חב על עובד שעוול במהלך עבודתו (ס׳ 13).</li><li>שולח (14); אין אחריות לקבלן עצמאי, למעט חריגים (15).</li><li>מבחן ההשתלבות והפיקוח.</li></ul> <p style="margin-top:18px;padding-top:9px;border-top:1px solid var(--line,#3a342a);font-size:11px;color:var(--muted,#8a8475)">© כל הזכויות שמורות ל<b>אילן פרץ</b> · אין להעתיק, לשכפל או להפיץ ללא רשות בכתב.</p>']
CASES=[("ס' 13 לפקודת הנזיקין — אחריות מעביד", '', 'מעביד חב על עוולת עובדו שבוצעה במהלך העבודה ובמסגרת התפקיד — המקרה השכיח של אחריות שילוחית.'), ("ס' 14 — אחריות שולח", '', 'שולח חב על עוולת שלוחו בביצוע השליחות.'), ("ס' 15 — קבלן עצמאי", '', 'ככלל אין אחריות שילוחית למעשי קבלן עצמאי; מבחן ההשתלבות/הפיקוח מבחין עובד מקבלן.'), ('ע״א 502/78 מדינת ישראל נ׳ ניסים', 'צה״ל העסיק נהג אזרחי למשימה חד-פעמית. הנהג התרשל וגרם לתאונה שבה נהרג אזרח עובד צה״ל, ונשאלה השאלה אם המדינה אחראית שילוחית למעשי הנהג.', 'השופט ברק הציע את מבחן "היד הארוכה": שלוח הוא מי שפועל כידו הארוכה של השולח ומבצע את רצונו, להבדיל מקבלן עצמאי שנוטל על עצמו משימה. מבחן עזר: האם הפעולה היא חלק אינטגרלי מפעילות השולח. נקבע גם שאפשר לתבוע את המעביד באחריות ישירה ושילוחית במקביל.'), ('ע״א 338/60 מדינת ישראל נ׳ מדר', 'אדם שעלה על טרמפ ברכב צבאי נהרג בתאונה שנגרמה בשל נהיגתו הרשלנית של הנהג הצבאי.', 'השופט אגרנט הציג את הגישות לאחריות עקיפה מול ישירה ונטה לראשונה. נקבע שהמעביד אחראי גם כשהעובד לא הוסמך לפעולה, ואף כשנאסרה עליו, כל עוד היא נעשתה במהלך העבודה ואין סטייה מהותית ממנה. הודגש גם תפקיד ההרתעה: הידיעה על האחריות מתמרצת פיקוח.'), ('ע״א 8199/01 עזבון מירו נ׳ מירו', 'שוטר שהיה בחופשה הותיר את אקדחו הטעון על ספה לצידו במפגש חברתי, ואורח נטל את האקדח, ירה במנוח והרגו.', 'השופטת דורנר קבעה שנשיאת הנשק נעשתה ברשות, והשארתו טעון היא ביצוע לא נאות של מעשה מורשה לפי ס׳ 13(ב), ולכן המדינה אחראית שילוחית. רשלנות חמורה של העובד אינה שוללת כשלעצמה את אחריות המעביד.'), ('ע״א 445/88 כונס הנכסים הרשמי נ׳ שטיבל', 'מנהל סניף בנק עסק במקביל לתפקידו בהשקעות פרטיות של כספי לקוחות, וההשקעות ירדו לטמיון. הבנק טען שהמנהל פעל למטרות של עצמו.', 'ברוב דעות נקבע שהבנק אחראי שילוחית: המנהל פעל בסניף, באצטלת הבנק ובתחום פעולות פיננסיות שהוסמך לבצע, ולכן נוצרה סמכות נחזית שהלקוח הסתמך עליה. העובדה שהמנהל הפיק טובת הנאה אישית אינה מכריעה.'), ('ע״א 8027/14 שורוש נ׳ שליאן', 'ערעור (נובמבר 2015) שבו נדרש בית המשפט העליון לפרשנות ס׳ 13 ולשאלה מתי מעשה פלילי של עובד מנתק את אחריות המעביד.', 'השופט עמית קבע שביצוע רשלני של העבודה אינו מוציא את המעשה מגדר העבודה. כדי לבחון אם עבירה ניתקה את הקשר שוקלים את מטרת העובד, את ההרשעה הפלילית וטיבה ואת שיקולי המדיניות. לפי מבחן המטרה הדומיננטית, כשהמטרה השלטת קשורה למשימת המעביד — יש אחריות. כשהמטרה פלילית והתוצאה אינה לוואי למטרה לגיטימית — אין.'), ('ע״א 748/82 עיריית תל אביב-יפו נ׳ מורד', 'קבלן שהעירייה שכרה לעבודות ברחוב הותיר דלי מלא סיד, וילד ששיחק במקום נכווה בעינו.', 'נקבע שחובת העירייה להימנע ממטרד בדרך הרבים היא חובה מוגברת, שאינה מתבטלת בכך שהביצוע נמסר לקבלן מקצועי. לכן העירייה חבה אף שהקבלן הוא שהתרשל: מעבירים את הביצוע, לא את החובה.'), ('ע״א 1649/09 (רע״א 775/11) פלקסר נ׳ מדינת ישראל–משטרת ישראל', 'דיון בבקשת חסינות של עובד ציבור לפי ס׳ 7א לפקודה, שהוכרע ב-11.8.2014.', 'זהו הפסק המנחה בסוגיית החסינות: הוא עוסק בנטל ההוכחה בבקשות לפי ס׳ 7א–7ג, במשקל תמיכת הרשות בבקשה ובשאלה מתי נדרש בירור עובדתי. נקבע שכאשר הרשות מגישה את הבקשה או תומכת בה, הנטל עובר לתובע להראות שתנאי החסינות לא התקיימו; כשהעובד מבקש והרשות מתנגדת — הנטל על העובד. הלכות אלה יושמו ברע״א 6821/21 דהרי נ׳ לדרמן (2022).')]
QS=[{'q': 'מה מבדיל אחריות שילוחית מאחריות ישירה של מעביד?', 'o': ['אין הבדל מעשי בין השתיים', 'באחריות שילוחית המעביד חב בשל עוולת עובדו גם בלי שהתרשל בעצמו; באחריות ישירה הוא חב בשל התרשלותו שלו', 'באחריות ישירה העובד פטור', 'אחריות שילוחית חלה רק על המדינה'], 'c': 1, 'e': 'נכון. בשילוחית מייחסים למעביד את עוולת העובד; בישירה המעביד עצמו הפר חובת זהירות (בחירה, הדרכה, פיקוח). אפשר לטעון לשתיהן במקביל.'}, {'q': 'אילו שלושה יסודות נדרשים לאחריות מעביד לפי ס׳ 13(א)(2)?', 'o': ['כוונה, נזק וקשר סיבתי', 'יחסי עובד–מעביד, עוולה של העובד, וביצועה תוך כדי העבודה', 'רשלנות המעביד, נזק ממון ואשם תורם', 'חוזה בכתב, תשלום שכר ומסמך מינוי'], 'c': 1, 'e': 'נכון. אלה שלושת היסודות המצטברים שעולים מלשון ס׳ 13.'}, {'q': 'נהג משאית של חברת הובלות קיבל הוראה מפורשת לא לאסוף טרמפיסטים. הוא אסף טרמפיסט, ונהג ברשלנות שגרמה לפציעתו. החברה טוענת שהנהג הפר הוראה. מה הדין?', 'o': ['רק הטרמפיסט אחראי כי עלה על דעת עצמו', 'החברה פטורה כי ההוראה הופרה', 'החברה עשויה להיות אחראית — מעשה שנאסר אך נעשה במהלך העבודה יכול להיות "תוך כדי עבודה" (מדר)', 'החברה אחראית רק אם אישררה בכתב'], 'c': 2, 'e': 'נכון. הנהיגה היא תפקידו הרגיל; גם מעשה אסור יכול להיות ביצוע לא נאות של העבודה, כל עוד אין סטייה מהותית.'}, {'q': 'חייל שקיבל רובה לשם הגנה מפני מסתננים יצא בעצמו לצוד תנים ופצע אדם. מה קבע ביהמ״ש בפרשה דומה (שאש נ׳ דלה)?', 'o': ['החייל פטור והמדינה אחראית', 'המדינה אחראית רק לחצי מהנזק', 'המדינה אינה אחראית — השימוש היה מחוץ לתפקיד ולא לטובת המעביד', 'המדינה אחראית כי הנשק שלה'], 'c': 2, 'e': 'נכון. צייד תנים היה סטייה מוחלטת מהתפקיד, למטרות של החייל עצמו — מחוץ לס׳ 13(ב).'}, {'q': 'שוטר בחופשה השאיר את אקדחו הטעון על ספה, ואורח שנטל את האקדח ירה והרג אדם. המדינה טוענת שהשוטר התרשל ברשלנות חמורה ולכן היא פטורה. מה הדין?', 'o': ['המדינה אחראית — זהו ביצוע לא נאות של מעשה מורשה, ורשלנות חמורה אינה שוללת אחריות שילוחית (מירו)', 'המדינה פטורה בגלל הרשלנות החמורה', 'המדינה אחראית רק אם השוטר היה בתפקיד באותה שעה', 'רק האורח אחראי'], 'c': 0, 'e': 'נכון. נשיאת הנשק הייתה ברשות; השארתו טעון היא ביצוע לא נאות. חומרת הרשלנות אינה מנתקת את האחריות.'}, {'q': 'מנהלת סניף בנק הציעה ללקוח "השקעה פרטית" במשרדה בסניף, והכספים נעלמו. הבנק טוען שפעלה למטרות של עצמה. מה ההלכה הרלוונטית?', 'o': ['הבנק פטור כי מדובר במטרות אישיות', 'ייתכן שהבנק אחראי מכוח סמכות נחזית (שטיבל)', 'הבנק אחראי רק אם ידע', 'הלקוח יכול לתבוע רק את המנהלת'], 'c': 1, 'e': 'נכון. פעולה בסניף, באצטלת הבנק ובתחום פעולות פיננסיות, יוצרת סמכות נחזית שמקימה אחריות שילוחית.'}, {'q': 'מה הקובע לפי ההגדרה בפקודה אם אדם הוא "מעביד"?', 'o': ['מי שחתום על חוזה עבודה', 'מי שמנכה מס הכנסה', 'מי שיש לו שליטה גמורה על הדרך שבה האחר מבצע עבודה בשבילו, ואילו עליו אין מרות דומה', 'מי שמשלם משכורת'], 'c': 2, 'e': 'נכון. זו לשון ס׳ 2; הפסיקה ריככה את מבחן השליטה והוסיפה את מבחן ההשתלבות.'}, {'q': 'מנתחת בכירה בבית חולים ציבורי מבצעת ניתוחים לפי שיקול דעתה המקצועי, ואיש בהנהלה אינו יכול להורות לה איך לנתח. האם בית החולים יכול לטעון שאינו "מעביד" שלה?', 'o': ['כן — רופאים לעולם אינם עובדים', 'קשה לו לטעון זאת — מבחן השליטה רוכך, ולפי מבחן ההשתלבות היא חלק אינטגרלי מהמערך', 'לא — כי היא מקבלת תלוש שכר', 'כן — אין שליטה גמורה בדרך הביצוע ולכן אין יחסי עבודה'], 'c': 1, 'e': 'נכון. הפסיקה ריככה את מבחן השליטה הגמורה; רופאה משולבת במבנה הארגוני של בית החולים ולכן נחשבת עובדת.'}, {'q': 'האם הגדרת "עובד" בפקודת הנזיקין זהה להגדרתו בדיני העבודה?', 'o': ['כן, אם יש חוזה בכתב', 'לא, דיני הנזיקין אינם מכירים בעובדים', 'לא — ההגדרה לעניין אחריות שילוחית עצמאית, ויכולות להיות תוצאות שונות', 'כן, תמיד'], 'c': 2, 'e': 'נכון. אדם עשוי להיחשב מעביד לעניין אחריות שילוחית אך לא לצורך זכויות עבודה, ולהפך.'}, {'q': 'מאבטח במועדון היכה בקבוק על ראשו של בליין אחרי שזה העליב את חברתו, ללא קשר לכניסה למועדון. לפי מבחני שורוש, מה צפוי?', 'o': ['המעביד אחראי כי מדובר בקטטה', 'סביר שהמעביד לא יחוב שילוחית — המטרה הדומיננטית הייתה נקמה אישית, לא משימת המעביד', 'המאבטח פטור כי פעל בעידנא דריתחא', 'המעביד אחראי תמיד למעשי מאבטח'], 'c': 1, 'e': 'נכון. לפי מבחן המטרה הדומיננטית, מעשה שנבע ממניע אישי ואינו קשור לתפקיד — לא ייוחס למעביד. עדיין ייבחנו רשלנות ישירה של המעביד ואחריות המאבטח.'}, {'q': 'מה קבע בית המשפט בפרשת רשות הנמלים נ׳ צים לגבי אחריות שולח לפי ס׳ 14?', 'o': ['שאחריות שולח מחייבת שליטה גמורה', 'שס׳ 14 חל רק על בנקים', 'שאין אחריות שולח בישראל', 'שאחריות שולח אינה מותנית בשליטה אלא במילוי מקום השולח בידי השלוח'], 'c': 3, 'e': 'נכון. די בכך שהשלוח ממלא את מקומו של השולח; לכן ייתכנו יחסי שליחות גם בלי יחסי עבודה.'}, {'q': 'מה ההבדל בין שלוח לבין קבלן עצמאי לפי מבחן "היד הארוכה" (ניסים)?', 'o': ['אין הבדל', 'קבלן תמיד תאגיד, שלוח תמיד יחיד', 'שלוח מקבל שכר, קבלן לא', 'שלוח פועל כידו הארוכה של השולח ומבצע את רצונו; קבלן נוטל על עצמו משימה ומבצעה באופן עצמאי'], 'c': 3, 'e': 'נכון. ברק הציע לבחון אם הפעולה היא חלק אינטגרלי מפעילות השולח או משימה עצמאית של הקבלן.'}, {'q': 'בעל דירה שכר שיפוצניק עצמאי מנוסה, והשיפוצניק הפיל בהתרשלות אריח מהמרפסת על עובר אורח. בעל הדירה לא התערב בעבודה. מה הכלל?', 'o': ['ככלל בעל הדירה אינו אחראי לעוולת קבלן עצמאי (ס׳ 15), אלא אם חל אחד החריגים', 'בעל הדירה אחראי שילוחית כמעביד', 'בעל הדירה אחראי תמיד כי זו דירתו', 'השיפוצניק פטור כי פעל בשביל אחר'], 'c': 0, 'e': 'נכון. ס׳ 15 פוטר מזמין מעוולות הקבלן, למעט חמישה חריגים (בחירה רשלנית, התערבות, הרשאה, חובה מכוח חיקוק, מטרה שלא כדין). כדאי לבדוק גם אחריות ישירה שלו.'}, {'q': 'עירייה שכרה קבלן לעבודות ברחוב; הקבלן השאיר דלי סיד פתוח וילד נכווה. העירייה טוענת שבחרה קבלן מקצועי. מה ההלכה?', 'o': ['העירייה אחראית — חובתה להימנע ממטרד בדרך הרבים היא חובה מוגברת שאינה ניתנת להעברה (מורד)', 'רק הילד אשם', 'העירייה אחראית רק אם התערבה', 'העירייה פטורה לפי ס׳ 15'], 'c': 0, 'e': 'נכון. בפרשת מורד נקבע שמעבירים את הביצוע אך לא את החובה; העירייה חבה גם כשהקבלן הוא שהתרשל.'}, {'q': 'מה קובע ס׳ 16 לפקודה?', 'o': ['שהמעביד פטור כשהעובד אחראי', 'שקבלן עצמאי אינו אחראי לעוולותיו', 'שאחריות המעביד לפי ס׳ 13 אינה גורעת מאחריות העובד עצמו', 'שהעובד פטור כשהמעביד אחראי'], 'c': 2, 'e': 'נכון. העובד נשאר אחראי למעשיו, והמעביד והעובד הם מעוולים יחד.'}, {'q': 'נגד פקח עירוני הוגשה תביעת נזיקין על פעולה שביצע במילוי תפקידו, ללא כוונה לגרום נזק. העירייה תומכת בבקשתו לחסינות. מה הדין?', 'o': ['הניזוק נותר ללא פיצוי', 'הפקח והעירייה פטורים שניהם', 'הפקח אחראי לבדו', 'התביעה נגד הפקח צפויה להידחות, והעירייה אחראית שילוחית במקומו (ס׳ 7א)'], 'c': 3, 'e': 'נכון. עובד רשות ציבורית שפעל בתפקיד שלטוני נהנה מחסינות אישית; הרשות אחראית לפי ס׳ 13–14. כשהרשות תומכת, הנטל לסתור את החסינות עובר לתובע.'}, {'q': 'מתי לא תחול חסינות עובד הציבור לפי ס׳ 7א?', 'o': ['כשהעובד זוטר', 'כשהנזק עולה על סכום מסוים', 'כשהעובד התרשל', 'כשהמעשה נעשה ביודעין מתוך כוונה לגרום נזק או בשוויון נפש לאפשרות גרימתו'], 'c': 3, 'e': 'נכון. זו לשון הסיפא של ס׳ 7א(א): כוונה לגרום נזק או שוויון נפש שוללים את החסינות.'}, {'q': 'מה מאפשר ס׳ 7ו לפקודה?', 'o': ['למדינה או לרשות לתבוע פיצוי או שיפוי מעובד ציבור שפעל בסטייה חמורה מהתנהגות ראויה', 'לניזוק לתבוע פיצויים עונשיים', 'לעובד לתבוע את המדינה', 'לבטל את חסינות השופטים'], 'c': 0, 'e': 'נכון. על אף החסינות, סטייה חמורה מקנה למדינה או לרשות פיצוי או שיפוי מהעובד, בסכום שיקבע ביהמ״ש על פי הצדק והיושר.'}, {'q': 'לפי לשון ס׳ 13(ב), מה לא ייראה כמעשה שנעשה תוך כדי העבודה?', 'o': ['מחדל של העובד', 'מעשה שעשה העובד למטרות של עצמו ולא לעניין המעביד', 'ביצוע לא נאות של מעשה שהמעביד הרשה', 'מעשה שנעשה בשעות נוספות'], 'c': 1, 'e': 'נכון. זו הסיפא של ס׳ 13(ב): מעשה למטרות העובד עצמו ולא לעניין המעביד.'}, {'q': 'איזה מבין החריגים הבאים אינו מנוי בס׳ 15 כחריג לפטור המזמין מעוולות קבלן עצמאי?', 'o': ['המזמין התערב בעבודה באופן שגרם לנזק', 'הדבר שלשמו נעשה החוזה היה שלא כדין', 'המזמין התרשל בבחירת הקבלן', 'המזמין שילם לקבלן מחיר נמוך מהמקובל'], 'c': 3, 'e': 'נכון. מחיר החוזה אינו אחד מחמשת החריגים; לכל היותר הוא ראיה לבחירה רשלנית.'}, {'q': 'קבלן ביצע עבודות חפירה עבור בעל מגרש, ושלל ברשלנות את התמיכה מבית השכן. בעל המגרש טוען שהקבלן עצמאי. מה ההלכה?', 'o': ['רק השכן אחראי לחיזוק ביתו', 'הקבלן פטור', 'בעל המגרש פטור לפי ס׳ 15', 'בעל המגרש חב — חובת התמיכה (ס׳ 48א) היא חובה מוגברת שאינה מתבטלת בשל אשמת הקבלן (ויג׳י שאה)'], 'c': 3, 'e': 'נכון. בויג׳י שאה נקבע שבעל הבית חב בשל הריסת התמיכה בידי קבלניו, משום שזו חובתו שלו.'}, {'q': 'אחריות מעביד מעוגנת ב:', 'o': ["ס' 13", "ס' 35", "ס' 63", "ס' 23"], 'c': 0, 'e': 'המקרה השכיח.'}, {'q': 'מעביד חב על עובד אם העוולה בוצעה:', 'o': ['בכל מקרה', 'במהלך עבודתו', 'רק בכוונה', 'רק מחוץ לעבודה'], 'c': 1, 'e': 'אגב מילוי התפקיד.'}, {'q': 'אחריות שולח-שלוח:', 'o': ["ס' 13", "ס' 14", "ס' 15", "ס' 64"], 'c': 1, 'e': 'יחסי שליחות.'}, {'q': 'אחריות למעשי קבלן עצמאי:', 'o': ['מלאה', "ככלל אין (ס' 15)", 'כפולה', 'כמו עובד'], 'c': 1, 'e': 'הקבלן פועל עצמאית.'}, {'q': 'מה מבחין עובד מקבלן עצמאי?', 'o': ['השכר', 'מבחן ההשתלבות והפיקוח', 'הגיל', 'הוותק'], 'c': 1, 'e': 'שילוב בארגון ופיקוח.'}]
